// Brief tests (matrix rows L13-L13c): byte-exact text of a full brief,
// omission accounting, and the too-large goal. The expected file is written
// by hand from B5, never generated by brief.ts.
import { expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { buildBrief, type BriefInput } from "../../src/loop/brief.js";

function fullInput(): BriefInput {
  return {
    item: {
      schemaVersion: "v1",
      id: "demo-d",
      repo: "example/demo-repo",
      title: "Repair the demo widget",
      goal: "The widget renders within one second.",
      issue: null,
      dod: [
        { id: "D1", text: "Widget renders.", done: false },
        { id: "D2", text: "Render takes under a second.", done: false },
      ],
      dependencies: [],
      status: "queued",
      statusReason: null,
      assignedHostAlias: null,
      branch: null,
      pullNumber: null,
      modelRouting: {
        preferredModel: "meta/muse-glimmer-30b",
        attempts: 0,
        fallbackUsed: false,
      },
      retryCount: 0,
      stallRounds: 0,
    },
    branch: "factory/demo-d",
    baseBranch: "main",
    previous: {
      outcome: "red-ci",
      failingChecks: ["gates", "macos-probe"],
      findings: {
        headSha: "0123456789abcdef0123456789abcdef01234567",
        list: [
          {
            severity: "high",
            location: "src/widget.ts:12",
            defect: "null dereference",
            scenario: "render with no props",
            fixDirection: "guard the props",
          },
          {
            severity: "medium",
            location: "src/widget.ts:40",
            defect: "slow loop",
            scenario: "render a large list",
            fixDirection: "batch the updates",
          },
          {
            severity: "low",
            location: "src/widget.ts:77",
            defect: "stale comment",
            scenario: "read the code",
            fixDirection: "update the comment",
          },
        ],
      },
    },
  };
}

test("a full brief matches the fixture byte for byte (L13, B5)", () => {
  const result = buildBrief(fullInput(), 65536);
  expect(result.kind).toBe("ok");
  if (result.kind === "ok") {
    const expected = readFileSync(
      join(import.meta.dir, "..", "fixtures", "loop", "brief-expected.txt"),
      "utf8",
    );
    expect(result.brief).toBe(expected);
    expect(result.omittedFindings).toBe(0);
  }
});

test("a tight limit drops findings from the end with an omission line (L13b, B5)", () => {
  const findings = Array.from({ length: 60 }, (_, index) => ({
    severity: "low" as const,
    location: `src/widget.ts:${String(index + 1)}`,
    defect: `defect ${String(index + 1)}`,
    scenario: "read the code",
    fixDirection: "update the comment",
  }));
  const input: BriefInput = {
    ...fullInput(),
    previous: {
      outcome: "red-ci",
      failingChecks: [],
      findings: { headSha: "0123456789abcdef0123456789abcdef01234567", list: findings },
    },
  };
  const head = [
    "Work item demo-d: Repair the demo widget",
    "Repository example/demo-repo. Branch factory/demo-d from main.",
    "",
    "Goal:",
    "The widget renders within one second.",
    "",
    "Definition of done:",
    "- [ ] D1: Widget renders.",
    "- [ ] D2: Render takes under a second.",
    "",
    "Rules: Commit on factory/demo-d and push it to origin. Do not open a pull request. Do not push to main.",
    "",
    "Previous round: red-ci.",
    "Audit findings at 0123456789ab:",
    ...findings
      .slice(0, 10)
      .map(
        (finding) =>
          `- [${finding.severity}] ${finding.location}: ${finding.defect} Fix: ${finding.fixDirection}`,
      ),
    "(50 more findings omitted)",
  ];
  const expected = `${head.join("\n")}\n`;
  const limit = Buffer.byteLength(expected, "utf8");
  const kept = buildBrief(input, limit);
  expect(kept.kind).toBe("ok");
  if (kept.kind === "ok") {
    expect(kept.omittedFindings).toBe(50);
    expect(kept.brief).toBe(expected);
    expect(kept.brief).toContain("(50 more findings omitted)");
    expect(kept.brief).not.toContain("src/widget.ts:11");
    expect(kept.brief.match(/^- \[low\]/gm)).toHaveLength(10);
    expect(Buffer.byteLength(kept.brief, "utf8")).toBeLessThanOrEqual(limit);
  } else {
    throw new Error("expected an ok brief at the hand-computed limit");
  }
  const tighter = buildBrief(input, limit - 1);
  expect(tighter.kind).toBe("ok");
  if (tighter.kind === "ok") {
    expect(tighter.omittedFindings).toBe(51);
    expect(tighter.brief).not.toContain("src/widget.ts:10");
    expect(tighter.brief.match(/^- \[low\]/gm)).toHaveLength(9);
    expect(Buffer.byteLength(tighter.brief, "utf8")).toBeLessThanOrEqual(limit - 1);
  } else {
    throw new Error("expected an ok brief one byte below the limit");
  }
});

test("a goal larger than the limit is too large (L13c, B5)", () => {
  const input: BriefInput = { ...fullInput(), previous: null };
  const over = { ...input, item: { ...input.item, goal: "g".repeat(70000) } };
  const full = buildBrief(over, 1 << 30);
  expect(full.kind).toBe("ok");
  if (full.kind === "ok") {
    expect(buildBrief(over, 65536)).toEqual({
      kind: "too-large",
      bytes: Buffer.byteLength(full.brief, "utf8"),
    });
  }
});
